        st.params[P_LMH_MIX] = 500;
        let fl = st.to_bytes();
        a.state.project.mixer[1].slots[3] = Some(os_model::SlotPlugin { id: os_model::Id::NONE, name: MAXIMUS_FILE_NAME.into(), state: fl.clone() });
        a.sync_effects();
        let key = fx_key(1, 3);
        assert!(a.plugins.hosted.contains_key(&key));
