    #[test]
    fn monitor_switch_restores_main_hits_and_damage_without_repaint() {
        let mut app=App::new(None);app.state.project=test_project();
        let mut main=Canvas::new(1280,800,1.).unwrap();app.paint(&mut main,None);app.take_damage();
        let before:Vec<_>=app.hits.iter().map(|h|(h.action.clone(),h.rect)).collect();
        let size=app.state.screen;let grid=app.pl_grid;
        let pixels=main.pixmap.data().to_vec();
        let saved=app.take_view_context();
        app.state.native_view=Some(Win::Mixer);
        let mut other=Canvas::new(1800,1000,1.5).unwrap();app.paint(&mut other,None);app.invalidate();
        app.restore_view_context(saved);
        assert_eq!(app.hits.iter().map(|h|(h.action.clone(),h.rect)).collect::<Vec<_>>(),before);
        assert_eq!(app.state.screen,size);assert_eq!(app.pl_grid,grid);assert_eq!(app.state.ui_scale,1.);
        assert!(!app.has_damage(),"detached repaint must not dirty the main window");
        assert_eq!(main.pixmap.data(),pixels);assert_eq!(app.state.native_view,None);
    }

    #[test]
    fn playlist_automation_spans_existing_clips_and_respects_manual_bounds() {
        use crate::playlist as pl;
        use os_model::{Clip, ClipSource, Note, target};
        for cut in [false, true] {
            let mut app = App::new(None);
            app.state.project = test_project();
            app.state.project.patterns[0].notes.push(Note::step(0, 0));
            let source = ClipSource::Pattern(1);
            pl::arr_mut(&mut app.state).clips = vec![
                Clip::new(384, 384, 2, source),
                Clip::new(1152, 384, 2, source),
                Clip::new(2304, 384, 3, source),
            ];
            app.state.playlist.sel = vec![1];
            let ch = pl::create_automation(&mut app.state, target::slot_param(1, 0, 0), "Filter", 0.5);
            let auto = pl::clips(&app.state)[3].clone();
            assert_eq!((auto.track, auto.position, auto.end()), (2, 384, 1536));
            let owner = pl::clips(&app.state)[1].clone();
            app.state.playlist.stretch = true;
            assert!(pl::stretch_clip(&mut app.state, 1, &owner, owner.position, 768));
            pl::drag_end(&mut app, pl::PlDrag::ResizeR { x0: 0.0, orig: vec![(1, owner)] },
                Rect::new(0.0, 0.0, 1200.0, 800.0));
            let extended = pl::clips(&app.state)[3].clone();
            assert_eq!(extended.end(), 1920);
            if cut {
                pl::split(&mut app.state, 3, 1152).unwrap();
            } else {
                pl::resize_right(&mut app.state, 3, &extended, 768);
            }
            let file = os_flp::project::create(&app.state.project).unwrap();
            app.state.project = os_flp::project::load(&os_flp::FlpFile::parse(&file.to_bytes().unwrap()).unwrap()).unwrap();
            let bounds = |s: &State| pl::clips(s).iter().filter(|c| c.source == ClipSource::Channel(ch))
                .map(|c| (c.position, c.end(), c.window)).collect::<Vec<_>>();
            let before = bounds(&app.state);
            assert!(before.iter().all(|(_, _, window)| window.is_some()));
            app.state.playlist.source = Some(source);
            pl::place(&mut app.state, 2, 3072);
            assert_eq!(bounds(&app.state), before);
        }
    }

    #[test]
    fn playlist_copies_extend_one_linked_automation_curve() {
        use crate::playlist as pl;
        use os_model::{ChannelKind, Clip, ClipSource, target};
        for reopened in [false, true] {
            let mut app = App::new(None);
            app.state.project = test_project();
            app.state.project.channels[0].kind = ChannelKind::AudioClip;
            let source = ClipSource::Channel(0);
            pl::arr_mut(&mut app.state).clips = vec![Clip::new(384, 768, 2, source)];
            let ch = pl::create_automation(&mut app.state, target::slot_param(1, 0, 0), "Filter", 0.5);
            pl::add_point(&mut app.state, ch, 2.0, 0.7);
            pl::run(&mut app, pl::Cmd::TrackAutomationToggle(2));
            if reopened {
                let file = os_flp::project::create(&app.state.project).unwrap();
                app.state.project = os_flp::project::load(&os_flp::FlpFile::parse(&file.to_bytes().unwrap()).unwrap()).unwrap();
                app.state.playlist.automation_owners.clear();
            }
            let curve = app.state.project.automation(ch).unwrap().clone();
            let automation = |s: &State| {
                let mut placed = pl::clips(s).iter().filter(|c| c.source == ClipSource::Channel(ch));
                let clip = placed.next().expect("automation clip").clone();
                assert!(placed.next().is_none(), "there must be a single automation instance");
                clip
            };
            let owner = pl::clips(&app.state).iter().position(|c| c.source == source).unwrap();
            app.state.playlist.sel = vec![owner];
            pl::snapshot(&mut app.state);
            pl::duplicate(&mut app.state);
            assert_eq!(app.state.playlist.sel.len(), 1);
            assert_eq!(automation(&app.state).end(), 1920);
            crate::history::undo(&mut app.state);
            assert_eq!(automation(&app.state).end(), 1152);
            app.state.playlist.sel = vec![owner];
            pl::copy(&mut app.state);
            assert_eq!(app.state.playlist.clipboard.len(), 1);
            app.state.playlist.pos = 2304;
            pl::paste(&mut app.state);
            assert_eq!(automation(&app.state).end(), 3072);
            app.state.playlist.source = Some(source);
            let last = pl::place(&mut app.state, 2, 4000);
            assert_eq!(automation(&app.state).end(), pl::clips(&app.state)[last].end());
            assert_eq!(automation(&app.state).position, 384);
            pl::run(&mut app, pl::Cmd::TrackAutomationToggle(2));
            assert_eq!(app.state.playlist.automation_views.get(&2), Some(&ch));
            assert_eq!(app.state.project.automation(ch), Some(&curve));
        }
    }

    #[test]
    fn mixer_plugin_automation_uses_insert_row_and_edits_points() {
        use crate::playlist as pl;
        use winit::keyboard::{Key, NamedKey};
        let mut app = App::new(None);
        app.state.project = test_project();
        pl::arr_mut(&mut app.state).clips.clear();
        let ch = pl::create_automation(&mut app.state, os_model::target::slot_param(22, 0, 1), "Filter", 0.5);
        let clip = pl::clips(&app.state)[0].clone();
        assert_eq!(clip.track, 21);
        assert_eq!(app.state.playlist.automation_views.get(&21), Some(&ch));
        app.state.playlist.track = 21;
        app.state.playlist.row_h = 100.0;
        let grid = Rect::new(0.0, 0.0, 1200.0, 3000.0);
        let g = pl::PGeom::new(&app.state, grid);
        let body = g.body(&clip);
        let x = g.clip_rect(&clip).x + 20.0;
        let y = body.cy();
        app.state.playlist.tool = pl::PlTool::Paint;
        app.mouse = (x, y);
        pl::press_grid(&mut app, grid, false);
        let drag = match app.drag.take() {
            Some(Drag::Pl(d @ pl::PlDrag::PointPaint { .. })) => d,
            _ => panic!("Brush should start point painting"),
        };
        app.mouse = (x + 20.0, y);
        pl::drag_move(&mut app, drag, grid);
        let count = app.state.project.automation(ch).unwrap().points.len();
        assert!(count > 3);
        app.drag = None;
        app.state.playlist.tool = pl::PlTool::Select;
        pl::press_grid(&mut app, grid, false);
        assert!(pl::key(&mut app, &Key::Named(NamedKey::Delete), false, false));
        assert!(app.state.project.automation(ch).unwrap().points.len() < count);
        assert_eq!(pl::clips(&app.state).len(), 1);
        let point = app.state.project.automation(ch).unwrap().points[1];
        app.mouse = (pl::point_x(&app.state, &g, &clip, point.beat), pl::value_y(body, point.value));
        let count = app.state.project.automation(ch).unwrap().points.len();
        pl::press_grid(&mut app, grid, true);
        assert_eq!(app.state.project.automation(ch).unwrap().points.len(), count - 1);
        assert_eq!(pl::clips(&app.state).len(), 1);
    }

    #[test]
    fn automation_overlay_follows_loop_and_supports_strip_controls() {
        use crate::{playlist as pl,knobs::KnobId as K};
        use os_model::{Clip,ClipSource,ChannelKind,target};
        let mut app=App::new(None);app.state.project=test_project();
        app.state.project.channels[0].kind=ChannelKind::AudioClip;
        app.state.project.channels[0].mixer_track=10;
        app.state.project.channels[0].name=Some("Hi-hat loop".into());
        app.state.project.channels[0].sample_path=Some("automation-hat-fixture.wav".into());
        let peaks=(0..1500).map(|i|{let a=((i%95) as f32/95.0*7.0).exp().recip()*0.9;(-a,a)}).collect();
        app.state.playlist.waves.borrow_mut().insert("automation-hat-fixture.wav".into(),Some(std::rc::Rc::new(pl::Wave{fine:Default::default(),rate:48000,frames:96000,per:64,peaks})));
        pl::arr_mut(&mut app.state).clips=vec![Clip::new(384,768,2,ClipSource::Channel(0))];
        app.state.playlist.sel=vec![0];app.state.show_browser=false;
        app.state.z=vec![Win::Mixer];
        let mut c=Canvas::new(1920,1080,1.25).unwrap();frame(&mut app,&mut c,None);
        for k in [K::MixPan(10),K::MixSep(10),K::Strip(10,0),K::Strip(10,1),K::Eq(10,0,0),K::Eq(10,1,1),K::Eq(10,2,0)] {
            assert!(app.automation_target(&Action::Knob(k)).is_some(),"{k:?}");
        }
        let knob=hit_rect(&app,&Action::Knob(K::Strip(10,0)));
        app.mouse_move(knob.cx(),knob.cy());app.mouse_down_right();
        let cmd=app.state.playlist.popup.as_ref().unwrap().items.iter().find(|i|i.label=="Create automation clip").unwrap().cmd.clone();
        pl::run(&mut app,cmd);
        let auto=app.state.project.automations.last().unwrap().channel;
        assert_eq!(app.state.project.automation(auto).unwrap().targets,vec![target::strip(10,0)]);
        let overlay=pl::clips(&app.state).last().unwrap().clone();
        assert_eq!((overlay.track,overlay.position,overlay.length),(2,384,768));
        assert_eq!(app.state.playlist.automation_views.get(&2),Some(&auto));
        app.state.z=vec![Win::Playlist];app.state.playlist.row_h=100.0;app.state.playlist_bar_w=220.0;
        frame(&mut app,&mut c,None);let grid=app.pl_grid().unwrap();let g=pl::PGeom::new(&app.state,grid);
        let base=pl::clips(&app.state)[0].clone();assert_eq!(g.clip_rect(&base),g.clip_rect(&overlay));
        let x=g.x_of(600.0);let y=pl::value_y(g.body(&overlay),0.65);
        assert_eq!(pl::clips(&app.state)[pl::clip_at(&app.state,&g,x,y).unwrap()].source,overlay.source);
        app.state.playlist.tool = pl::PlTool::Draw;
        app.mouse=(x,y);let count=app.state.project.automation(auto).unwrap().points.len();
        pl::press_grid(&mut app,grid,true);assert_eq!(app.state.project.automation(auto).unwrap().points.len(),count+1);
        app.state.playlist.popup=None;app.state.playlist.hover_clip=Some(1);
        let before=app.state.project.clone();
        frame(&mut app,&mut c,None);
        let switch=hit_rect(&app,&Action::PlAutomationToggle(2));
        app.mouse_move(switch.cx(),switch.cy());app.mouse_down();app.mouse_up();
        assert_eq!(app.state.project,before,"hide is visual only");
        let hidden=pl::PGeom::new(&app.state,grid);assert!(hidden.clip_rect(&overlay).x<0.0);assert!(hidden.clip_rect(&base).x>=grid.x);
        pl::automation_menu(&mut app.state,2,(400.0,200.0));
        assert!(app.state.playlist.popup.as_ref().unwrap().items.iter().any(|i|i.cmd==pl::Cmd::TrackAutomation(2,Some(auto))));
        app.state.playlist.popup=None;
        pl::run(&mut app,pl::Cmd::TrackAutomationToggle(2));
        assert_eq!(app.state.playlist.automation_views.get(&2),Some(&auto));
        app.state.project.arrangements.push(os_flp::project::default_arrangement());
        let mut saved=os_flp::project::create(&app.state.project).unwrap();
        let bytes=saved.to_bytes().unwrap();let loaded=os_flp::project::load(&os_flp::FlpFile::parse(&bytes).unwrap()).unwrap();
        assert_eq!(loaded.automation(auto).unwrap().targets,vec![target::strip(10,0)]);
        assert!(loaded.arrangements[0].clips.iter().any(|c|c.source==overlay.source&&c.track==2&&c.position==384&&c.length==768));
        if let Some(dir)=std::env::var_os("OS_SHOT_DIR") {frame(&mut app,&mut c,None);c.pixmap.save_png(std::path::PathBuf::from(dir).join("automation-overlay.png")).unwrap();}
        app.state.project=loaded;app.state.playlist.automation_views.clear();app.state.playlist.automation_owners.clear();
        assert!(pl::PGeom::new(&app.state,grid).clip_rect(&overlay).x<0.0,"reload keeps shared-row automation hidden until chosen");
    }

    #[test]
    fn dragging_automation_off_its_overlay_keeps_its_own_track() {
        use crate::playlist as pl;
        use os_model::{Clip, ClipSource, target};

        let mut app = App::new(None);
        app.state.project = test_project();
        app.state.show_browser = false;
        app.state.z = vec![Win::Playlist];
        app.state.playlist.tool = pl::PlTool::Draw;
        app.state.playlist.row_h = 64.0;
        app.state.playlist_bar_w = 220.0;
        pl::arr_mut(&mut app.state).clips = vec![
            Clip::new(0, 768, 1, ClipSource::Pattern(1)),
            Clip::new(0, 768, 3, ClipSource::Pattern(1)),
        ];
        let channel = pl::create_automation(&mut app.state, target::mixer(0, target::MIXER_VOLUME), "Volume", 0.7);
        let source = ClipSource::Channel(channel);
        let arrangement = pl::arr_mut(&mut app.state);
        arrangement.clips[2].track = 1;
        arrangement.clips[2].position = 0;
        arrangement.clips[2].length = 384;
        arrangement.clips.push(Clip::new(384, 384, 1, source));
        arrangement.tracks[2].locked = true;
        pl::run(&mut app, pl::Cmd::TrackAutomation(1, Some(channel)));
        let automation = app.state.project.automation(channel).unwrap().clone();
        let mut canvas = Canvas::new(1920, 1080, 1.0).unwrap();
        frame(&mut app, &mut canvas, None);
        let grid = app.pl_grid().unwrap();
        let g = pl::PGeom::new(&app.state, grid);
        let title = g.clip_rect(&pl::clips(&app.state)[2]);
        let x = title.cx();
        let title_offset = 5.0;
        app.mouse_move(x, title.y + title_offset);
        app.mouse_down();
        app.mouse_move(x, g.y_of(2) + title_offset);
        assert_eq!(pl::clips(&app.state)[2].track, 1, "locked rows reject the drop");
        app.mouse_move(x, g.y_of(3) + title_offset);
        let during_drag = pl::PGeom::new(&app.state, grid);
        assert_eq!(during_drag.clip_rect(&pl::clips(&app.state)[2]).y, during_drag.y_of(3));
        app.mouse_up();

        let moved = &pl::clips(&app.state)[2];
        assert_eq!((moved.track, moved.position, moved.length, moved.source), (3, 0, 384, source));
        assert_eq!(app.state.project.automation(channel), Some(&automation));
        assert_eq!(pl::clips(&app.state)[3].track, 1);
        assert_eq!(during_drag.automation_overlay_row(&pl::clips(&app.state)[3]), Some(1));
        crate::history::undo(&mut app.state).unwrap();
        assert_eq!(pl::clips(&app.state)[2].track, 1);
        assert!(!pl::clips(&app.state)[2].independent_automation);
        crate::history::redo(&mut app.state).unwrap();
        assert_eq!(pl::clips(&app.state)[2].track, 3);

        frame(&mut app, &mut canvas, None);
        let g = pl::PGeom::new(&app.state, grid);
        let sibling = g.clip_rect(&pl::clips(&app.state)[3]);
        app.mouse_move(sibling.cx(), sibling.y + title_offset);
        app.mouse_down();
        app.mouse_move(sibling.cx(), g.y_of(4) + title_offset);
        app.mouse_up();
        assert_eq!(pl::clips(&app.state)[3].track, 4);
        assert!(!app.state.playlist.automation_views.contains_key(&1));
        assert_eq!(app.state.project.automation(channel), Some(&automation));

        let saved = os_flp::project::create(&app.state.project).unwrap().to_bytes().unwrap();
        app.state.project = os_flp::project::load(&os_flp::FlpFile::parse(&saved).unwrap()).unwrap();
        app.state.playlist.automation_views.clear();
        app.state.playlist.automation_owners.clear();
        let reopened = pl::clips(&app.state).iter().find(|clip| clip.source == source && clip.position == 0).unwrap();
        let g = pl::PGeom::new(&app.state, grid);
        assert_eq!(g.clip_rect(reopened).y, g.y_of(3), "the clip stays visible on its occupied destination after reopening");
        assert_eq!(app.state.project.automation(channel).unwrap().targets, automation.targets);
    }

    #[test]
    fn round2_automation_lane_and_separator() {
        crate::settings_file::set_flag("declutter_toolbar", true);
        use crate::playlist as pl;
        let mut app = App::new(None);
        app.state.project = test_project();
        pl::arr_mut(&mut app.state).clips.push(os_model::Clip::new(0, 384, 0, os_model::ClipSource::Channel(0)));
        let a = pl::create_automation(&mut app.state, os_model::target::CHANNEL_VOLUME as u32, "Volume", 0.5);
        let b = pl::create_automation(&mut app.state, os_model::target::CHANNEL_PAN as u32, "Pan", 0.5);
        let before = pl::clips(&app.state).to_vec();
        let mut canvas = Canvas::new(1920, 1080, 1.0).unwrap();
        app.state.z = vec![Win::Playlist];
        frame(&mut app, &mut canvas, None);
        assert!(!app.hits.iter().any(|h| h.action == Action::Util(Util::Undo)));
        let button = hit_rect(&app, &Action::PlAutomation(0));
        click(&mut app, &mut canvas, button);
        assert!(app.state.playlist.popup.as_ref().is_some_and(|p| p.items.iter().any(|i| i.cmd == pl::Cmd::TrackAutomation(0, Some(a)))));
        app.state.playlist.popup = None;
        let had_cpu = app.hits.iter().any(|h| h.action == Action::CpuPanel);
        app.toolbar_switch(views::toolbar::Switch::CpuMemory);
        frame(&mut app, &mut canvas, None);
        assert_ne!(app.hits.iter().any(|h| h.action == Action::CpuPanel), had_cpu);
        let grid = os_ui::Rect::new(300.0, 140.0, 1200.0, 800.0);
        pl::run(&mut app, pl::Cmd::TrackAutomation(0, Some(a)));
        let g = pl::PGeom::new(&app.state, grid);
        let auto = before.iter().find(|c| c.source == os_model::ClipSource::Channel(a)).unwrap();
        assert_eq!(g.clip_rect(auto).y, g.y_of(0));
        assert!(g.rows.height(auto.track)>0.0);
        assert!(g.clip_rect(&before[0]).x >= grid.x);
        let ci = pl::clip_at(&app.state, &g, g.clip_rect(auto).x + 5.0, g.clip_rect(auto).y + 20.0).unwrap();
        assert_eq!(pl::clips(&app.state)[ci].source, os_model::ClipSource::Channel(a));
        pl::run(&mut app, pl::Cmd::TrackAutomation(0, Some(b)));
        assert_eq!(app.state.playlist.automation_views.get(&0), Some(&b));
        assert_eq!(pl::clips(&app.state), before.as_slice(), "view changes never move saved clips");
        pl::run(&mut app, pl::Cmd::TrackAutomationSeparate(0));
        assert!(app.state.playlist.automation_owners.is_empty());
        crate::mixer::run(&mut app, crate::mixer::MCmd::Separator(1));
        assert!(crate::mixer::has_separator(&app.state, 1));
        crate::mixer::run(&mut app, crate::mixer::MCmd::Separator(1));
        assert!(!crate::mixer::has_separator(&app.state, 1));
    }

    #[test]
    fn traditional_readouts_partial_repaint() {
        use crate::mixer::{self as mx,MHit};
        let mut c=Canvas::new(1920,1080,1.).unwrap();
        let mut full=Canvas::new(1920,1080,1.).unwrap();
        let mut app=App::new(None);
        app.state.z=vec![Win::Mixer];
        app.state.startup_layout_pending=false;
        app.state.wins[Win::Mixer.slot().unwrap()]=WinState{rect:Rect::new(0.,83.,1500.,660.),maxed:false,mini:false};
        for mode in [3,4] {
            mx::set_layout(&mut app.state,mx::TRADITIONAL+mode);
            frame(&mut app,&mut c,None);
            let picker=hit_rect(&app,&Action::Mix(MHit::Layout));
            let detach=hit_rect(&app,&Action::DetachWin(Win::Mixer));
            assert!(picker.right()+10.<=detach.x,"dropdown needs space before Detach");
            let fader=hit_rect(&app,&Action::Fader(1));
            app.mouse_move(fader.cx(),fader.cy());app.mouse_down();
            frame(&mut app,&mut c,None);app.take_damage();
            for dy in [-18.,29.,-3.,60.] {
                app.mouse_move(fader.cx(),fader.cy()+dy);
                let damage=app.take_damage();
                frame_damage(&mut app,&mut c,damage);
                frame(&mut app,&mut full,None);
                let changed=c.pixmap.data().iter().zip(full.pixmap.data()).filter(|(a,b)|a.abs_diff(**b)>3).count();
                let points:Vec<_>=c.pixmap.data().iter().zip(full.pixmap.data()).enumerate().filter(|(_, (a,b))|a.abs_diff(**b)>3).map(|(i,_)|((i/4)%1920,(i/4)/1920)).collect();
                let bbox=points.iter().fold((usize::MAX,usize::MAX,0,0),|b,&(x,y)|(b.0.min(x),b.1.min(y),b.2.max(x),b.3.max(y)));
                assert_eq!(changed,0,"partial fader/hint repaint must equal full: mode {mode}, dy {dy}, bbox {bbox:?}, hint {:?}, fader {fader:?}",views::band_rect(&app.state,HINT_RECT));
            }
            app.mouse_up();
        }
        // Replacing a wrapped hint by a short hint must clear both old lines completely.
        for hint in ["This longer mixer hint wraps across both lines of the hint panel", "Volume -inf dB", "Compact mixer view", ""] {
            app.hint=Cow::Owned(hint.into());
            app.damage_band(HINT_RECT);
            let damage=app.take_damage();frame_damage(&mut app,&mut c,damage);
            frame(&mut app,&mut full,None);
            let r=views::band_rect(&app.state,HINT_RECT).outset(3.);
            for y in r.y.max(0.) as u32..r.bottom().min(1080.) as u32 {
                for x in r.x.max(0.) as u32..r.right().min(1920.) as u32 {
                    let i=((y*1920+x)*4) as usize;
                    assert!(c.pixmap.data()[i..i+4].iter().zip(&full.pixmap.data()[i..i+4]).all(|(a,b)|a.abs_diff(*b)<=3),"stale hint pixel at {x},{y}");
                }
            }
        }
    }

    #[test]
    fn mixer_batch_insert_confirms_from_the_starter_project_menu() {
        use crate::dialog::DHit;
        use crate::mixer::{self as mx, MCmd, MHit};
        use os_model::target::{self, Target};
        use winit::keyboard::Key;

        let mut app = App::new(None);
        let mut file = os_flp::FlpFile::parse(include_bytes!("../assets/templates/Lemon Starter.flp")).unwrap();
        app.state.project = os_flp::project::load(&file).unwrap();
        app.state.z = vec![Win::Mixer];
        app.state.startup_layout_pending = false;
        app.state.show_browser = false;
        app.state.mixer_scroll = 0.;
        assert_eq!(mx::inserts(&app.state), 125);
        let mut canvas = Canvas::new(1500, 900, 1.).unwrap();
        frame(&mut app, &mut canvas, None);
        let strip = hit_rect(&app, &Action::Mix(MHit::Strip(2)));
        let title = Rect::new(strip.cx(), strip.y + 3., 0., 0.);
        click(&mut app, &mut canvas, title);
        assert!(app.state.playlist.popup.is_none(), "left-click selects without a context menu");
        app.mouse_down_right();
        app.mouse_up();
        frame(&mut app, &mut canvas, None);
        let row = app.state.playlist.popup.as_ref().unwrap().items.iter()
            .position(|item| item.cmd == crate::playlist::Cmd::Mixer(MCmd::InsertMultiple(2))).unwrap();
        let item = hit_rect(&app, &Action::PlPopup(row));
        click(&mut app, &mut canvas, item);
        assert!(app.modal_open());
        app.key(&Key::Character("4".into()), false, false);
        frame(&mut app, &mut canvas, None);
        let confirm = hit_rect(&app, &Action::Dlg(DHit::Accept));
        click(&mut app, &mut canvas, confirm);
        assert!(!app.modal_open());
        assert_eq!(mx::selected(&app.state), [3, 4, 5, 6]);
        assert_eq!(mx::inserts(&app.state), 129);

        // The high insert and its send must survive in both the automation IDs and the saved project.
        let high = mx::track_mut(&mut app.state, 129).unwrap();
        high.name = Some("High insert".into());
        high.pan = Some(0.2);
        let source = mx::track_mut(&mut app.state, 1).unwrap();
        source.routes.push(129);
        source.send_levels.push((129, 0.5));
        let send = target::send(1, 129);
        let pan = target::mixer(129, target::MIXER_PAN);
        assert_eq!(target::decode(send), Target::MixerSend(1, 129));
        assert_eq!(target::decode(pan), Target::MixerPan(129));
        assert_eq!(target::decode(target::strip(129, 4)), Target::MixerStrip(129, 4));
        assert_eq!(target::decode(target::slot_param(129, 14, 6)), Target::SlotParam(129, 14, 6));
        app.state.project.init_controls.push(os_model::InitControl { head: 0, target: send, value: 8000 });
        os_flp::project::apply(&app.state.project, &mut file).unwrap();
        let saved = os_flp::project::load(&file).unwrap();
        assert_eq!(saved.mixer.len(), 131);
        assert_eq!(saved.mixer[129].name.as_deref(), Some("High insert"));
        assert!((saved.mixer[129].pan.unwrap() - 0.2).abs() < 0.001);
        assert!(saved.mixer[1].routes.contains(&129));
        assert!(saved.mixer[1].send_levels.contains(&(129, 0.5)));
        assert!(saved.init_controls.iter().any(|control| control.target == send));
    }

    #[test]
    fn mixer_routing_deck_preserves_channel_selection() {
        use crate::knobs::KnobId;
        use crate::mixer::{self as mx, MHit};
        let mut canvas = Canvas::new(1500, 900, 1.).unwrap();
        for (vintage, layout) in [
            (false, mx::WIDE),
            (false, mx::TRADITIONAL),
            (false, crate::rack_mixer::VIEW),
            (true, mx::WIDE),
            (true, mx::TRADITIONAL),
        ] {
            let mut app = App::new(None);
            app.state.project = test_project();
            app.state.z = vec![Win::Mixer];
            app.state.startup_layout_pending = false;
            app.state.vintage_2005 = vintage;
            mx::set_layout(&mut app.state, layout);
            mx::select(&mut app.state, 1, false);
            frame(&mut app, &mut canvas, None);

            let strip = hit_rect(&app, &Action::Mix(MHit::Strip(2)));
            let route = Action::Mix(MHit::Route(2));
            let target = hit_rect(&app, &route);
            assert!(strip.intersect(&target).is_empty());
            let edge_x = strip.x + 1.;
            let deck_top = strip.bottom() + 1.;
            for y in [deck_top, target.cy()] {
                assert_eq!(
                    app.top_hit(edge_x, y).map(|hit| &hit.action),
                    Some(&Action::MixerArea),
                    "vintage={vintage}, layout={layout}, y={y}"
                );
                click(&mut app, &mut canvas, Rect::new(edge_x, y, 0., 0.));
                assert_eq!(app.state.selected_mixer, 1);
                assert!(mx::send(&app.state, 1, 2).is_none());
            }
            // A drag starting in the routing background cannot select the channel on release.
            app.mouse_move(edge_x, deck_top);
            app.mouse_down();
            app.mouse_move(strip.cx(), strip.y + 3.);
            app.mouse_up();
            assert_eq!(app.state.selected_mixer, 1);

            let x = target.right() - 2.;
            let y = target.bottom() - 2.;
            assert_eq!(app.top_hit(x, y).unwrap().action, route);
            click(&mut app, &mut canvas, Rect::new(x, y, 0., 0.));
            assert_eq!(app.state.selected_mixer, 1);
            let level = mx::send(&app.state, 1, 2).unwrap();

            let send = hit_rect(&app, &Action::Knob(KnobId::Send(1, 2)));
            app.mouse_move(send.cx(), send.cy());
            app.mouse_down();
            app.mouse_move(send.cx(), send.cy() + 18.);
            app.mouse_up();
            assert_eq!(app.state.selected_mixer, 1);
            assert!(mx::send(&app.state, 1, 2).unwrap() < level);

            let remove = hit_rect(&app, &Action::Mix(MHit::Unroute(2)));
            click(&mut app, &mut canvas, remove);
            assert_eq!(app.state.selected_mixer, 1);
            assert!(mx::send(&app.state, 1, 2).is_none());

            click(&mut app, &mut canvas, Rect::new(strip.cx(), strip.y + 3., 0., 0.));
            assert_eq!(app.state.selected_mixer, 2);
        }
    }

    #[test]
    fn traditional_mixer_layouts_controls_and_persistence() {
        use crate::knobs::KnobId;
        use crate::mixer::{self as mx,MHit};
        let mut c=Canvas::new(1920,1080,1.).unwrap();
        let mut app=App::new(None);
        app.state.z=vec![Win::Mixer];
        app.state.startup_layout_pending=false;
        let original=app.state.project.clone();
        for left in [false,true] {
            crate::prefs::set_text("mixer_inspector_left",if left {"true"} else {"false"});
            for height in [435.,660.,997.] {
                app.state.wins[Win::Mixer.slot().unwrap()]=WinState{rect:Rect::new(0.,83.,1500.,height),maxed:false,mini:false};
                for i in 0..8 {
                    mx::set_layout(&mut app.state,mx::TRADITIONAL+i);
                    app.state.mixer_scroll=0.;
                    frame(&mut app,&mut c,None);
                    for action in [Action::Fader(0),Action::Fader(1),Action::Mix(MHit::Effects(1)),Action::Mix(MHit::Disk(1)),Action::Knob(KnobId::MixPan(1))] {
                        let r=hit_rect(&app,&action);
                        assert!(r.w>0. && r.h>0. && r.x.is_finite() && r.y.is_finite(),"{i}: {action:?} {r:?}");
                    }
                    let fader=hit_rect(&app,&Action::Fader(1));
                    let record=hit_rect(&app,&Action::Mix(MHit::Disk(1)));
                    assert!(fader.intersect(&record).is_empty(),"record/fader overlap {i}");
                    let picker=hit_rect(&app,&Action::Mix(MHit::Layout));
                    let close=hit_rect(&app,&Action::CloseWin(Win::Mixer));
                    assert!(picker.right()<close.x && picker.x>hit_rect(&app,&Action::Mix(MHit::View(mx::TRADITIONAL+i))).right());
                    let menu=mx::layout_menu(&app.state,0.,0.);
                    assert_eq!(menu.items.len(),mx::TRADITIONAL_LAYOUTS.len()+1);
                    assert!(menu.items.iter().any(|v|matches!(v.cmd,crate::playlist::Cmd::Mixer(mx::MCmd::Layout(crate::rack_mixer::VIEW)))));
                    assert!(menu.items.iter().all(|v|matches!(v.cmd,crate::playlist::Cmd::Mixer(mx::MCmd::Layout(_)))));
                    if i==7 {assert!(app.hits.iter().any(|h|h.action==Action::Mix(MHit::TrackSlot(1,0))));}
                    crate::layout::save(&app.state);
                    let mut restored=App::new(None);
                    crate::layout::restore(&mut restored.state);
                    assert_eq!(restored.state.mixer.layout,mx::TRADITIONAL+i);
                    mx::set_layout(&mut restored.state,mx::WIDE);
                    assert_eq!(restored.state.mixer.traditional_layout,i);
                }
            }
        }
        assert_eq!(app.state.project.mixer,original.mixer,"switching layouts must not change audio state");
        mx::set_layout(&mut app.state,mx::WIDE);
        frame(&mut app,&mut c,None);
        let hint=app.hits.iter().find(|h|h.hint=="Hint bar").expect("hint panel").rect;
        let toolbar_scale=crate::views::band_k(&app.state);
        assert!(hint.w>0. && toolbar_scale>0.);
        for text in ["Compact mixer view","Full mixer view"] {
            assert!(c.text_width(os_ui::Font::new(13),text)<hint.w/toolbar_scale-10.);
        }
        // Empty per-track slots select the correct target before opening the add-effect menu.
        mx::hit(&mut app,MHit::TrackSlot(1,0));
        assert_eq!(app.state.selected_mixer,1);
        assert!(app.state.playlist.popup.is_some());
    }

