        app.state.project.mixer[70].name=Some("Vocal mix".into());app.state.project.mixer[70].color=Some(Rgb{r:120,g:180,b:220});
        pl::arr_mut(&mut app.state).clips.push(Clip::new(0,96,3,ClipSource::Channel(0)));
